edit_file("index.html", `<!DOCTYPE html>
<html>
<head><title>s07</title></head>
<body>
<h2>s07</h2>
<input type="text" id="filterbox">
<div id="people">
  <p class="item">nadia</p>
  <p class="item">nasser</p>
  <p class="item">oleg</p>
  <p class="item">priya</p>
  <p class="item">ravi</p>
</div>
<script>
const field = document.getElementById('filterbox');
const rows = Array.from(document.querySelectorAll('#people .item'));
function apply() {
  const q = field.value.toLowerCase();
  rows.forEach(function (el) {
    const hit = el.textContent.toLowerCase().indexOf(q) !== -1;
    el.style.display = hit ? '' : 'none';
  });
}
field.addEventListener('keyup', apply);
</script>
</body>
</html>`)
